definition.raw:
let
$\eta$ be a smooth bump function with a small support, fix $l \in
\mathbb{N}$ and define for each integer $n\ge0$ the following projections
\begin{align}
\label{eq:201}
	\Xi_{n}(\xi)
	=\sum_{a/q \in\mathscr{U}_{n^l}}
	 \eta\big(\mathcal E_n^{-1}(\xi - a/q)\big)
      \end{align}
where  $\mathcal E_n$
is a diagonal $d\times d$  matrix with positive entries
$\big(\varepsilon_{j}: 1\le j\le d\big)$ such that
$\varepsilon_{j}\le e^{-n^{1/5}}$   and
\[
\mathscr{U}_{n^l}=\big\{a/q \in \mathbb{T}^d\cap\mathbb{Q}^d : a=(a_1, \ldots, a_d) \in
\mathbb{N}^d_q \text{ and } \mathrm{gcd}(a_1, \ldots, a_d, q)=1 \text{ and }
q\in P_{n^l}\big\}
\]
for some family $P_{n^l}$ such that $\mathbb{N}_{n^l}\subseteq
P_{n^l}\subseteq \mathbb{N}_{e^{n^{1/10}}}$.

we define 
\[
\mathcal R(S)=\big\{a/q \in \mathbb{T}^d\cap\mathbb{Q}^d : a \in A_q \text{ and }
q\in S\big\}
\] 
where for each $q\in\mathbb{N}$ 
\[
A_q=\big\{a\in\mathbb{N}_q^d: \mathrm{gcd}\big(q, \mathrm(a_{\gamma}: \gamma\in\Gamma)\big)\big\}.
\]
Finally, for each $N\in\mathbb{N}$ we will consider the sets
\begin{align}
  \label{eq:156}
\mathscr{U}_N=\mathcal R(P_N).

we define new periodic  multipliers
\begin{align}
	\label{eq:74}
	\Delta_N(\xi)
	=\sum_{a/q \in\mathscr{U}_N}
	 \Theta(\xi - a/q) \eta_N(\xi - a/q)
      \end{align}
where $\eta_N(\xi)=\eta\big(\mathcal E_N^{-1}\xi\big)$ and $\mathcal E_N$
is a diagonal $d\times d$  matrix with  positive entries
$(\varepsilon_{\gamma}: \gamma\in\Gamma)$ such that
$\varepsilon_{\gamma}
\le e^{-N^{2\rho}}$.

\label{def:1}
A subset $\Lambda\subseteq \Pi(V)$ has
$\mathcal O$ property if there is $k\in\mathbb{N}_D$ and there are sets 
$S_1, S_2,\ldots, S_k$ with the following properties:
\begin{enumerate}
\item[(i)] for each $1\le j\le k$ there is $
  \beta_j\in\mathbb{N}$ such that $S_j=\{q_{j, 1},\ldots, q_{j, \beta_j}\}$;
\item[(ii)] for every $q_{j, s}\in S_j$ there are $p_{j, s}\in V$ and
  $\gamma_j\in\mathbb{N}_D$ such that $q_{j, s}=p_{j, s}^{\gamma_j}$;
\item[(iii)] for every $w\in W$ there are unique numbers $q_{1, s_1}\in
  S_1,\ldots, q_{k, s_k}\in S_k$ such that $w=q_{1,
    s_1}\cdot\ldots\cdot q_{k, s_k}$;
\item[(iv)] if $(j, s)\not=(j', s')$ then $(q_{j, s}, q_{j', s'})=1$. 
\end{enumerate}

Let 
        \begin{align}
          \label{eq:300}
\Lambda \subseteq \Pi(\mathbb P_N)\cup\{1\}          
        \end{align}
        be a set with $\mathcal O$ property, see Definition
        \ref{def:1}.

We define the Weyl sums
\begin{align}
  \label{eq:215}
	S_N = \sum_{n \in \Omega_N \cap \mathbb{Z}^k} e^{2\pi i P(n)}\varphi(n)
\end{align}
where  $\varphi:\mathbb{R}^k\mapsto \mathbb{C}$ is  a continuously differentiable function which for some $C>0$ satisfies
\begin{align}
  \label{eq:217}
|\varphi(x)|\le C, \qquad \text{and} \qquad |\nabla \varphi(x)|\le C(1+|x|)^{-1}.

theorem.raw:
\label{thm:0}
        For every $p \in (1, \infty)$ there is $C_p > 0$ such that for all
		$f \in \ell^p\big(\mathbb{Z}^{d_0}\big)$
                \begin{align}
                  \label{eq:35}
		\big\lVert
		T^\mathcal{P} f 
		\big\rVert_{\ell^p}
		\leq
		C_p \vnorm{f}_{\ell^p}.
                \end{align}
		Moreover, the constant $C_p$ is independent of the coefficients of the polynomial mapping 
		$\mathcal{P}$.

\label{thm:7}
        For every $p \in (1, \infty)$ there is $C_p > 0$ such that for all
		$f \in \ell^p\big(\mathbb{Z}^{d}\big)$
                \begin{align}
\label{eq:37}
		\big\lVert
		T^\mathcal{Q} f 
		\big\rVert_{\ell^p}
		\leq
		C_p \vnorm{f}_{\ell^p}.
                \end{align}

\label{th:3}
	Let $\Theta$ be a  multiplier on $\mathbb{R}^d$ obeying \eqref{eq:155}. 
	Then for every $\rho>0$ and $p\in(1, \infty)$ there is a
        constant $C_{\rho, p} > 0$ such that
	for any $N\in\mathbb{N}$ and $f \in \ell^p\big(\mathbb{Z}^d\big)$
	\begin{align}
		\label{eq:12}
		\big\lVert
		\mathcal{F}^{-1}\big(\Delta_{N}
		\hat{f}\big)\big\rVert_{\ell^p} 
		\leq C_{\rho, p} (\mathbf{A}_p+1)\log N
		\vnorm{f}_{\ell^p}.
	\end{align}

\label{thm:500}
Suppose that $\rho>0$ and $r\in\mathbb{N}$ are given. Then there is a
constant $C_{\rho, r}>0$ such that for any $N>8^{2r/\rho}$ and for any
set $\Lambda$ as in \eqref{eq:300}
and for every $f\in\ell^{2r}\big(\mathbb{Z}^d\big)$ we have  
\begin{align}
  \label{eq:677}
  \Big\|\sum_{u\in \mathcal U_{\mathbb{N}_k}}f_u\Big\|_{\ell^{2r}}\le C_{\rho, r}\|f\|_{\ell^{2r}}.
\end{align}
Moreover, the integer $k\in\mathbb{N}_D$, the set $\mathcal U_{\mathbb{N}_k}$ and consequently  the sets $S_1,\ldots, S_k$
 are determined by the set $\Lambda$ as it was described  above.

\label{thm:5}
Suppose that $\rho>0$ and $r\in\mathbb{N}$ are given. Then there is a
constant $C_{\rho, r}>0$ such that for any $N>8^{2r/\rho}$ and for any
set $\Lambda$ as in \eqref{eq:300}
and for every $f\in\ell^{2r}\big(\mathbb{Z}^d\big)$ we have  
\begin{align}
  \label{eq:130}
  \Big\|\sum_{u\in\mathcal U_{\mathbb{N}_k}}
  f_{u}\Big\|_{\ell^{2r}}^{2r}
\le C_{\rho, r}\sum_{\atop{M\subseteq \mathbb{N}_k}{M=\{j_1, \ldots,
    j_m\}}}\sum_{\sigma\in\mathbb{N}_{\beta_{j_1}}\times\ldots\times\mathbb{N}_{\beta_{j_m}}}
\big\|\mathcal S_{M, M}^{\sigma}\big(f_u:u\in\mathcal
  U_{\mathbb{N}_k}\big)\big\|_{\ell^{2r}}^{2r}.
\end{align}
Moreover, the integer $k\in\mathbb{N}_D$, the set $\mathcal U_{\mathbb{N}_k}$ and consequently  the sets $S_1,\ldots, S_k$
 are determined by the set $\Lambda$ as it was described  above the
 formulation of
 Theorem \ref{thm:500}.

\label{thm:3}
        Assume that there is a multi-index $\gamma_0$ such that $0 < \norm{\gamma_0} \leq d$ and
	\[
		\Big\lvert
		\xi_{\gamma_0} - \frac{a}{q}
		\Big\rvert
		\leq
		\frac{1}{q^2}
	\]
        for some integers $a, q$ such that $0\le a\le q$ and $(a, q) =
        1$. Then for any $\alpha>0$ there is  $\beta_{\alpha}>0$ so that, for any
        $\beta\ge \beta_{\alpha}$, if
	\begin{equation}
		\label{eq:57}
		(\log N)^\beta \leq q \leq N^{\norm{\gamma_0}} (\log N)^{-\beta}
	\end{equation}
        then there is a constant $C>0$ 
	\begin{equation}
		\label{eq:56}
		|S_N|
		\leq
		C
		N^k (\log N)^{-\alpha}.
	\end{equation}
	The implied  constant $C$ is independent of $N$.

\label{thm:30}
For every
$p\in(1, \infty)$ there is a
constant $C_p>0$ such that for all $-\infty\le M_1\le M_2\le \infty$,
$j\in\mathbb{Z}$ and $N\in\mathbb{N}$ and every  $f\in\ell^p\big(\mathbb{Z}^d\big)$ we have
 \begin{align}
   \label{eq:23}
   \bigg\|\Big(\sum_{M_1\le n\le M_2}\big|\mathcal
  F^{-1}\big(\Omega_{N}^{j, n}\hat{f}\big)\big|^2\Big)^{1/2}\bigg\|_{\ell^p}\le C_p \log N\|f\|_{\ell^p}.
 \end{align}

lemma.raw:
\label{lem:12}
For every $\rho>0$ there exists a constant $C_{\rho}>0$ such that for
every $N\in\mathbb{N}$ the set $\mathscr{U}_N$ can be written as a
disjoint union of at most $C_{\rho}\log N$ sets
$\mathscr{U}_N^i=\mathcal R(P_N^i)$ where
\begin{align}
  \label{eq:14}
   P_N^i =\big\{
  q=Q\cdot w: Q|Q_0\ \text{and}\ w\in {\Lambda}_i(\mathbb P_N)\big\}
\end{align}
and 
${\Lambda}_i(\mathbb P_N)
\subseteq \Pi(\mathbb P_N)\cup\{1\}$ has $\mathcal O$ property
for each integer $1\le i\le C_{\rho}\log N$.

proposition.raw:
\label{prop:0}
 There is a constant $C>0$ such
  that for every $n\in\mathbb{N}$ and for every $\xi\in [1/2, 1/2)^d$ satisfying 
        $$
	\Big\lvert \xi_\gamma - \frac{a_\gamma}{q} \Big\rvert \leq
        L_1^{-|\gamma|}L_2
	$$
	for all $\gamma \in \Gamma$, where  $1\le q\le L_3\le 2^{n/2}$, $a\in
        A_q$, $L_1\ge 2^n$  and $L_2\ge1$ we have 
        \begin{align}
          \label{eq:41}
          \big|m_n(\xi)-G(a/q)\Phi_{n}(\xi-a/q)\big|\le 
          C\Big(L_32^{-n}
          +L_2L_32^{-n}\sum_{\gamma \in
            \Gamma}\big(2^n/L_1\big)^{|\gamma|}\Big)\le CL_2L_32^{-n}.
        \end{align}

proof.raw:
Under the assumptions of Theorem \ref{thm:500}, there is a constant
$C_r>0$ such that for any $M\subseteq\mathbb{N}_k$ and $L=\{j_1,\ldots,
j_l\}\subseteq M$ and $j_n\in M\setminus L$ and for any
$\sigma=(s_{j_1}, \ldots,
s_{j_l})\in\mathbb{N}_{\beta_{j_1}}\times\ldots\times\mathbb{N}_{\beta_{j_l}}$
determined by the set $L$ we have
\begin{align}
  \label{eq:119}
 \big\| \mathcal S_{L, M}^{\sigma}\big(f_u:u\in\mathcal
  U_{\mathbb{N}_k}\big)\big\|_{\ell^{2r}}\le C_r\Big\|\big\|\mathcal
  S_{L\cup\{j_n\}, M}^{\sigma\oplus s_{j_n}}\big(f_u:u\in\mathcal
  U_{\mathbb{N}_k}\big)\big\|_{\ell^2_{s_{j_n}}}\Big\|_{\ell^{2r}}
\end{align}
where $\sigma\oplus s_{j_n}=(s_{j_1},\ldots,s_{j_l},
s_{j_n})\in
\mathbb{N}_{\beta_{j_1}}\times\ldots\times\mathbb{N}_{\beta_{j_l}}\times\mathbb{N}_{\beta_{j_n}}$
is the sequence determined by the set
$L\cup\{s_{j_n}\}$. Moreover, the right-hand side in \eqref{eq:119}
can be controlled in the following way
\begin{multline}
  \label{eq:129}
  \Big\|\big\|\mathcal
  S_{L\cup\{j_n\}, M}^{\sigma\oplus s_{j_n}}\big(f_u:u\in\mathcal
  U_{\mathbb{N}_k}\big)\big\|_{\ell^2_{ s_{j_n}}}\Big\|_{\ell^{2r}}^{2r}
\le C_r\sum_{s_{j_n}\in\mathbb{N}_{\beta_{j_n}}}
 \big\|\mathcal S_{L\cup\{j_n\}, M}^{\sigma\oplus s_{j_n}}\big(f_u:u\in\mathcal
  U_{\mathbb{N}_k}\big)\big\|_{\ell^{2r}}^{2r}\\
+C_r\big\|\mathcal S_{L, M\setminus\{j_n\}}^{\sigma}\big(f_u:u\in\mathcal
  U_{\mathbb{N}_k}\big)\big\|_{\ell^{2r}}^{2r}.
\end{multline}
The proof of \eqref{eq:119} and \eqref{eq:129} can be found in
\cite{mst1}. Therefore, \eqref{eq:119} combined with 
  \eqref{eq:129} yields
\begin{align}
  \label{eq:1190}
\begin{split}
 \big\| \mathcal S_{L, M}^{\sigma}\big(f_u:u\in\mathcal
  U_{\mathbb{N}_k}\big)\big\|_{\ell^{2r}}^{2r}&\le 
C_r\sum_{s_{j_n}\in\mathbb{N}_{\beta_{j_n}}}
 \big\|\mathcal S_{L\cup\{j_n\}, M}^{\sigma\oplus s_{j_n}}\big(f_u:u\in\mathcal
  U_{\mathbb{N}_k}\big)\big\|_{\ell^{2r}}^{2r}\\
&+C_r\big\|\mathcal S_{L, M\setminus\{j_n\}}^{\sigma}\big(f_u:u\in\mathcal
  U_{\mathbb{N}_k}\big)\big\|_{\ell^{2r}}^{2r}.
\end{split}
\end{align}
Applying \eqref{eq:1190} recursively we obtain 

\begin{multline}
  \label{eq:131}
\Big\|\sum_{u\in\mathcal U_{\mathbb{N}_k}}
  f_{u}\Big\|_{\ell^{2r}}^{2r}=\big\|\mathcal S_{\emptyset,
    \mathbb{N}_k}\big(f_u: u\in\mathcal
  U_{\mathbb{N}_k}\big)\big\|_{\ell^{2r}}^{2r}\\
\lesssim _r  
\sum_{s_{k}\in\mathbb{N}_{\beta_{j_k}}}
 \big\|\mathcal S_{\{k\}, \mathbb{N}_k}^{(s_{k})}\big(f_u:u\in\mathcal
  U_{\mathbb{N}_k}\big)
\big\|_{\ell^{2r}}^{2r}
+\big\|\mathcal S_{\emptyset, \mathbb{N}_{k-1}}\big(f_u:u\in\mathcal
  U_{\mathbb{N}_k}\big)
\big\|_{\ell^{2r}}^{2r}\\
\lesssim_r
\sum_{s_{k-1}\in\mathbb{N}_{\beta_{j_{k-1}}}}\sum_{s_{k}\in\mathbb{N}_{\beta_{j_k}}}
 \big\|\mathcal S_{\{k-1, k\}, \mathbb{N}_k}^{(s_{k-1}, s_{k})}\big(f_u:u\in\mathcal
  U_{\mathbb{N}_k}\big)
\big\|_{\ell^{2r}}^{2r}+
\sum_{s_{k}\in\mathbb{N}_{\beta_{j_k}}}
 \big\|\mathcal S_{\{k\}, \mathbb{N}_{k}\setminus\{k-1\}}^{(s_{k})}\big(f_u:u\in\mathcal
  U_{\mathbb{N}_k}\big)
\big\|_{\ell^{2r}}^{2r}\\
+\sum_{s_{k-1}\in\mathbb{N}_{\beta_{j_{k-1}}}}
 \big\|\mathcal S_{\{k-1\}, \mathbb{N}_{k-1}}^{(s_{k-1})}\big(f_u:u\in\mathcal
  U_{\mathbb{N}_k}\big)
\big\|_{\ell^{2r}}^{2r}
+\big\|\mathcal S_{\emptyset, \mathbb{N}_{k-2}}\big(f_u:u\in\mathcal
  U_{\mathbb{N}_k}\big)
\big\|_{\ell^{2r}}^{2r}\\
\lesssim_r\ldots\lesssim_{\rho, r}\sum_{\atop{M\subseteq \mathbb{N}_k}{M=\{j_1, \ldots,
    j_m\}}}\sum_{\sigma\in\mathbb{N}_{\beta_{j_1}}\times\ldots\times\mathbb{N}_{\beta_{j_m}}}
\sum_{x\in\mathbb{Z}^d}\bigg(\sum_{w\in\mathcal
  U_{M^c}}\Big|\sum_{v\in\mathcal V_{M}^{\sigma}}f_{w+v}(x)\Big|^2\bigg)^r.
\end{multline}
 The proof of \eqref{eq:130} is completed.

We assume, without of loss of generality, that $N\in\mathbb{N}$ is large.
Let $B_h=q_{j_1, s_{j_1}}\cdot\ldots\cdot q_{j_m,
  s_{j_m}}\cdot Q_0\le e^{N^{\rho}}$
and observe that according to the notation from \eqref{eq:25} and \eqref{eq:13},  we
have
\begin{multline}
  \label{eq:136}
  \big\|\mathcal S_{M, M}^{\sigma}\big(f_u:u\in\mathcal
  U_{\mathbb{N}_k}\big)\big\|_{\ell^{2r}}^{2r}=
\sum_{x\in\mathbb{Z}^d}\bigg(\sum_{w\in\mathcal
  U_{M^c}}\Big|\sum_{v\in\mathcal V_{M}^{\sigma}}f_{w+v}(x)\Big|^2\bigg)^r\\
\le\sum_{x\in\mathbb{Z}^d}\bigg(\sum_{w\in\mathcal
  U_{M^c}}\Big|\mathcal{F}^{-1}\Big(\sum_{v\in\mathcal V_{M}^{\sigma}}\sum_{b\in\mathbb{N}_{Q_0}}\Theta(\xi-b/Q_0-v-w)\eta_N(\xi-b/Q_0-v-w)\hat{f}(\xi)\Big)(x)\Big|^2\bigg)^r\\
=\sum_{n\in \mathbb{N}_{B_h}^d}\sum_{x\in\mathbb{Z}^d}\bigg(\sum_{w\in\mathcal
  U_{M^c}}\big|\mathcal{F}^{-1}\big(\Theta\eta_N G(\: \cdot\: ;n, w)\big)(B_hx+n)\big|^2\bigg)^r
\end{multline}
where 
\begin{align}
  \label{eq:137}
  G(\xi; n, w)=\sum_{v\in\mathcal V_{M}^{\sigma}}\sum_{b\in\mathbb{N}_{Q_0}^d}\hat{f}(\xi+b/Q_0+v+w)e^{-2\pi i
(b/Q_0+v)\cdot n}.
\end{align}

We  know that for each $0<p<\infty$ there is a constant $C_p>0$ such
that for any $d\in\mathbb{N}$ and $\lambda_1,\ldots,\lambda_d\in\mathbb{C}^d$ we have
\begin{align}
  \label{eq:1411}
  \bigg(\int_{\mathbb{C}^d}|\lambda_1z_1+\ldots+\lambda_dz_d|^pe^{-\pi
  |z|^2} {\rm d} z\bigg)^{1/p}=C_p\big(|\lambda_1|^2+\ldots+|\lambda_d|^2\big)^{1/2}.
\end{align}

By Proposition 4.5 from \cite{mst1}, with the sequence of multipliers
$\Theta_N=\Theta$ for all $N\in\mathbb{N}$ and $\Theta$ as in \eqref{eq:155},   we have 
\begin{align}
\label{eq:140}
\big\|\mathcal{F}^{-1}\big(\Theta\eta_N G(\: \cdot\: ;n,
w)\big)(B_hx+n)\big\|_{\ell^{2r}(x)}\le C_{\rho, r}\mathbf A_{2r}
\big\|\mathcal{F}^{-1}\big(\eta_N G(\: \cdot\: ;n, w)\big)(B_hx+n)\big\|_{\ell^{2r}(x)}
\end{align}
since $\inf_{\gamma\in\Gamma}\varepsilon_{\gamma}^{-1}\ge
e^{N^{2\rho}}\ge 2e^{(d+1)N^{\rho}}\ge B_h$ for sufficiently large
$N\in\mathbb{N}$. 

Therefore, combining \eqref{eq:140} with \eqref{eq:1411} we obtain that
\begin{multline}
  \label{eq:142}
\sum_{n\in \mathbb{N}_{B_h}^d}\sum_{x\in\mathbb{Z}^d}\bigg(\sum_{w\in\mathcal
  U_{M^c}}\big|\mathcal{F}^{-1}\big(\Theta\eta_N G(\: \cdot\: ;n, w)\big)(B_hx+n)\big|^2\bigg)^r
\\=C_{2r}^{2r}\int_{\mathbb{C}^d}
\sum_{n\in \mathbb{N}_{B_h}^d}\sum_{x\in\mathbb{Z}^d}\Big|\mathcal{F}^{-1}\Big(\Theta\eta_N\Big(\sum_{w\in\mathcal
	U_{M^c}}z_{w} G(\: \cdot\: ;n, w)\Big)\Big)(B_hx+n)\Big|^{2r}e^{-\pi |z|^2}{\rm d}z\\
\lesssim_r\int_{\mathbb{C}^d}
\sum_{n\in \mathbb{N}_{B_h}^d}\sum_{x\in\mathbb{Z}^d}\Big|\mathcal{F}^{-1}\Big(\sum_{w\in\mathcal
	U_{M^c}}z_{w} \eta_NG(\: \cdot\: ;n, w)\Big)(B_hx+n)\Big|^{2r}e^{-\pi |z|^2}{\rm d}z\\
\lesssim_r\sum_{n\in \mathbb{N}_{B_h}^d}\sum_{x\in\mathbb{Z}^d}\bigg(\sum_{w\in\mathcal
  U_{M^c}}\big|\mathcal{F}^{-1}\big(\eta_N G(\: \cdot\: ;n, w)\big)(B_hx+n)\big|^2\bigg)^r\\
\lesssim_r\sum_{x\in\mathbb{Z}^d}\bigg(\sum_{w\in\mathcal
  U_{M^c}}\Big|\mathcal{F}^{-1}\Big(\sum_{v\in\mathcal V_{M}^{\sigma}}\sum_{b\in\mathbb{N}_{Q_0}}\eta_N(\xi-b/Q_0-v-w)\hat{f}(\xi)\Big)(x)\Big|^2\bigg)^r.
\end{multline}
This completes the proof of Proposition \ref{prop:5}.

It remains to show that  there exists a constant $C_{\rho, r}>0$
  such that for any $M=\{j_1,\ldots, j_m\}\subseteq\mathbb{N}_{k}$ any $\sigma=(s_{j_1},\ldots,
s_{j_m})\in\mathbb{N}_{\beta_{j_1}}\times\ldots\times\mathbb{N}_{\beta_{j_m}}$
determined by the set $M$ and $f\in\ell^{2r}\big(\mathbb{Z}^d\big)$ we
have
\begin{align}
  \label{eq:143}
\sum_{\sigma\in\mathbb{N}_{\beta_{j_1}}\times\ldots\times\mathbb{N}_{\beta_{j_m}}}\Big\|\mathcal S_{M,
    M}^{\sigma}\Big(\mathcal
  F^{-1}\Big(\sum_{b\in\mathbb{N}_{Q_0}}\eta_N(\xi-b/Q_0-u)\hat{f}(\xi)\Big):u\in\mathcal
  U_{\mathbb{N}_k}\Big)\Big\|_{\ell^{2r}}^{2r}\le C_{\rho, r}^{2r}\|f\|_{\ell^{2r}}.
\end{align}
Since there are $2^k$ possible choices of sets $M\subseteq \mathbb{N}_k$ and $k\in\mathbb{N}_D$
then \eqref{eq:134} will follow and the proof of Theorem \ref{thm:500}
will be completed. If $r=1$ the then Plancherel's theorem does the job
since the  functions $\eta_N(\xi-b/Q_0-v-w)$ are disjointly supported 
for all $b/Q_0\in \mathbb{N}_{Q_0}$, $w\in\mathcal
  U_{M^c}$, $v\in\mathcal V_{M}^{\sigma}$ and $\sigma=(s_{j_1},\ldots,
s_{j_m})\in\mathbb{N}_{\beta_{j_1}}\times\ldots\times\mathbb{N}_{\beta_{j_m}}$. For
general $r\ge2$, since $\|f\|_{\ell^{2r}}^{2r}=\|f\|_{\ell^{2}}^2$
because we have assumed that $f$ is a characteristic function of a
finite set in $\mathbb{Z}^d$, it
suffices to prove for any $x\in\mathbb{Z}^d$ that
\begin{align}
  \label{eq:139}
  \sum_{w\in\mathcal
  U_{M^c}}\Big|\mathcal{F}^{-1}\Big(\sum_{v\in\mathcal V_{M}^{\sigma}}\sum_{b\in\mathbb{N}_{Q_0}}\eta_N(\xi-b/Q_0-v-w)\hat{f}(\xi)\Big)(x)\Big|^2\le
C_{\rho, r}.
\end{align}
In fact, since $\|f\|_{\ell^{\infty}}=1$, it is enough to show 
\begin{align}
  \label{eq:144}
  \Big\|\mathcal{F}^{-1}\Big(\sum_{w\in\mathcal
  U_{M^c}}\alpha(w)\sum_{v\in\mathcal V_{M}^{\sigma}}\sum_{b\in\mathbb{N}_{Q_0}}\eta_N(\xi-b/Q_0-v-w)\Big)\Big\|_{\ell^1}\le
C_{\rho, r}
\end{align}
for any sequence of complex numbers $\big(\alpha(w):  w\in\mathcal
  U_{M^c}\big)$ such that
  \begin{align}
    \label{eq:50}
    \sum_{w\in\mathcal
  U_{M^c}}|\alpha(w)|^2=1.
  \end{align}
Computing the Fourier transform we obtain 
\begin{multline}
  \label{eq:145}
  \mathcal{F}^{-1}\Big(\sum_{w\in\mathcal
    U_{M^c}}\alpha(w)\sum_{v\in\mathcal V_{M}^{\sigma}}\sum_{b\in\mathbb{N}_{Q_0}}\eta_N(\xi-b/Q_0-v-w)\Big)\\
  =\Big(\sum_{w\in\mathcal U_{M^c}}\alpha(w)e^{-2\pi i x\cdot
    w}\Big)\cdot \det(\mathcal E_N)\mathcal
  F^{-1}\eta\big(\mathcal E_Nx\big)\cdot\Big(\sum_{v\in\mathcal
    V_{M}^{\sigma}}\sum_{b\in\mathbb{N}_{Q_0}}e^{-2\pi i
    x\cdot (b/Q_0+v)}\Big).
\end{multline}
The function 
\begin{align}
  \label{eq:146}
  \sum_{v\in\mathcal
    V_{M}^{\sigma}}\sum_{b\in\mathbb{N}_{Q_0}}e^{-2\pi i
    x\cdot (b/Q_0+v)}
\end{align}
 can be written as a sum of $2^m$ functions 
\begin{align}
  \label{eq:147}
  \sum_{b\in\mathbb{N}_{Q}}e^{-2\pi i
    x\cdot (b/Q)} =
\begin{cases} 
Q^d & \mbox{if } x \equiv 0 \pmod{Q}, \\
0   & \mbox{otherwise,} 
\end{cases}  
\end{align}
