\begin{align*}
  \Big(\sum_{w\in\mathcal U_{M^c}}\alpha(w)e^{-2\pi i x\cdot
    Qw}\Big)\cdot\mathcal
  F^{-1}\psi\big(Q\mathcal E_N x\big)=Q^{-d}\det(\mathcal E_N)^{-1}
  \sum_{w\in\mathcal U_{M^c}}\alpha(w)\mathcal
  F^{-1}\big(\psi\big(Q^{-1}\mathcal E_N^{-1}(\: \cdot-Qw) \big)\big)(x).
\end{align*}
 Therefore, Plancherel's theorem and the last identity yield  
 \begin{multline}
   \label{eq:58}
   Q^{d}\det(\mathcal E_N)\Big\|\Big(\sum_{w\in\mathcal U_{M^c}}\alpha(w)e^{-2\pi i Qx\cdot
    w}\Big)\cdot\mathcal
  F^{-1}\psi\big(Q\mathcal E_N x\big)\Big\|_{\ell^2(x)}^2\\=
\sum_{w\in\mathcal
  U_{M^c}}|\alpha(w)|^2\int_{\mathbb{R}^d}\big|\psi(\xi-\mathcal E_N^{-1}w)\big|^2{\rm
d}\xi+\sum_{\atop{w_1, w_2\in\mathcal
  U_{M^c}}{w_1\not=w_2}}\alpha(w_1)\overline{\alpha(w_2)}\int_{\mathbb{R}^d}\psi(\xi)\psi\big(\xi-\mathcal E_N^{-1}(w_1-w_2)\big){\rm
d}\xi.
 \end{multline}
The first sum on the right-hand side of \eqref{eq:58} is bounded in
view of \eqref{eq:50}. The second one vanishes since the function
$\psi$ is supported in $(-1/(8d), 1/(8d))^d$ and
$|\mathcal E_N^{-1}(w_1-w_2)|_{\infty}\ge e^{N^{2\rho}}N^{-2D}>1$,
for sufficiently large $N$.
The proof of Theorem \ref{thm:500} is completed.
\end{proof}

\begin{proof}



Under the assumptions of Theorem \ref{thm:500}, there is a constant
$C_r>0$ such that for any $M\subseteq\mathbb{N}_k$ and $L=\{j_1,\ldots,
j_l\}\subseteq M$ and $j_n\in M\setminus L$ and for any
$\sigma=(s_{j_1}, \ldots,
s_{j_l})\in\mathbb{N}_{\beta_{j_1}}\times\ldots\times\mathbb{N}_{\beta_{j_l}}$
determined by the set $L$ we have
\begin{align}
  \label{eq:119}
 \big\| \mathcal S_{L, M}^{\sigma}\big(f_u:u\in\mathcal
  U_{\mathbb{N}_k}\big)\big\|_{\ell^{2r}}\le C_r\Big\|\big\|\mathcal
  S_{L\cup\{j_n\}, M}^{\sigma\oplus s_{j_n}}\big(f_u:u\in\mathcal
  U_{\mathbb{N}_k}\big)\big\|_{\ell^2_{s_{j_n}}}\Big\|_{\ell^{2r}}
\end{align}
where $\sigma\oplus s_{j_n}=(s_{j_1},\ldots,s_{j_l},
s_{j_n})\in
\mathbb{N}_{\beta_{j_1}}\times\ldots\times\mathbb{N}_{\beta_{j_l}}\times\mathbb{N}_{\beta_{j_n}}$
is the sequence determined by the set
$L\cup\{s_{j_n}\}$. Moreover, the right-hand side in \eqref{eq:119}
can be controlled in the following way
\begin{multline}
  \label{eq:129}
  \Big\|\big\|\mathcal
  S_{L\cup\{j_n\}, M}^{\sigma\oplus s_{j_n}}\big(f_u:u\in\mathcal
  U_{\mathbb{N}_k}\big)\big\|_{\ell^2_{ s_{j_n}}}\Big\|_{\ell^{2r}}^{2r}
\le C_r\sum_{s_{j_n}\in\mathbb{N}_{\beta_{j_n}}}
 \big\|\mathcal S_{L\cup\{j_n\}, M}^{\sigma\oplus s_{j_n}}\big(f_u:u\in\mathcal
  U_{\mathbb{N}_k}\big)\big\|_{\ell^{2r}}^{2r}\\
+C_r\big\|\mathcal S_{L, M\setminus\{j_n\}}^{\sigma}\big(f_u:u\in\mathcal
  U_{\mathbb{N}_k}\big)\big\|_{\ell^{2r}}^{2r}.
\end{multline}
The proof of \eqref{eq:119} and \eqref{eq:129} can be found in
\cite{mst1}. Therefore, \eqref{eq:119} combined with 
  \eqref{eq:129} yields
\begin{align}
  \label{eq:1190}
\begin{split}
 \big\| \mathcal S_{L, M}^{\sigma}\big(f_u:u\in\mathcal
  U_{\mathbb{N}_k}\big)\big\|_{\ell^{2r}}^{2r}&\le 
C_r\sum_{s_{j_n}\in\mathbb{N}_{\beta_{j_n}}}
 \big\|\mathcal S_{L\cup\{j_n\}, M}^{\sigma\oplus s_{j_n}}\big(f_u:u\in\mathcal
  U_{\mathbb{N}_k}\big)\big\|_{\ell^{2r}}^{2r}\\
&+C_r\big\|\mathcal S_{L, M\setminus\{j_n\}}^{\sigma}\big(f_u:u\in\mathcal
  U_{\mathbb{N}_k}\big)\big\|_{\ell^{2r}}^{2r}.
\end{split}
\end{align}
Applying \eqref{eq:1190} recursively we obtain 

\begin{multline}
  \label{eq:131}
\Big\|\sum_{u\in\mathcal U_{\mathbb{N}_k}}
  f_{u}\Big\|_{\ell^{2r}}^{2r}=\big\|\mathcal S_{\emptyset,
    \mathbb{N}_k}\big(f_u: u\in\mathcal
  U_{\mathbb{N}_k}\big)\big\|_{\ell^{2r}}^{2r}\\
\lesssim _r  
\sum_{s_{k}\in\mathbb{N}_{\beta_{j_k}}}
 \big\|\mathcal S_{\{k\}, \mathbb{N}_k}^{(s_{k})}\big(f_u:u\in\mathcal
  U_{\mathbb{N}_k}\big)
\big\|_{\ell^{2r}}^{2r}
+\big\|\mathcal S_{\emptyset, \mathbb{N}_{k-1}}\big(f_u:u\in\mathcal
  U_{\mathbb{N}_k}\big)
\big\|_{\ell^{2r}}^{2r}\\
\lesssim_r
\sum_{s_{k-1}\in\mathbb{N}_{\beta_{j_{k-1}}}}\sum_{s_{k}\in\mathbb{N}_{\beta_{j_k}}}
 \big\|\mathcal S_{\{k-1, k\}, \mathbb{N}_k}^{(s_{k-1}, s_{k})}\big(f_u:u\in\mathcal
  U_{\mathbb{N}_k}\big)
\big\|_{\ell^{2r}}^{2r}+
\sum_{s_{k}\in\mathbb{N}_{\beta_{j_k}}}
 \big\|\mathcal S_{\{k\}, \mathbb{N}_{k}\setminus\{k-1\}}^{(s_{k})}\big(f_u:u\in\mathcal
  U_{\mathbb{N}_k}\big)
\big\|_{\ell^{2r}}^{2r}\\
+\sum_{s_{k-1}\in\mathbb{N}_{\beta_{j_{k-1}}}}
 \big\|\mathcal S_{\{k-1\}, \mathbb{N}_{k-1}}^{(s_{k-1})}\big(f_u:u\in\mathcal
  U_{\mathbb{N}_k}\big)
\big\|_{\ell^{2r}}^{2r}
+\big\|\mathcal S_{\emptyset, \mathbb{N}_{k-2}}\big(f_u:u\in\mathcal
  U_{\mathbb{N}_k}\big)
\big\|_{\ell^{2r}}^{2r}\\
\lesssim_r\ldots\lesssim_{\rho, r}\sum_{\atop{M\subseteq \mathbb{N}_k}{M=\{j_1, \ldots,
    j_m\}}}\sum_{\sigma\in\mathbb{N}_{\beta_{j_1}}\times\ldots\times\mathbb{N}_{\beta_{j_m}}}
\sum_{x\in\mathbb{Z}^d}\bigg(\sum_{w\in\mathcal
  U_{M^c}}\Big|\sum_{v\in\mathcal V_{M}^{\sigma}}f_{w+v}(x)\Big|^2\bigg)^r.
\end{multline}
 The proof of \eqref{eq:130} is completed.
\end{proof}

